package com.benabdallah.csvpipeline.stub; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/imports") public class ImportController {private final Map<String,String> requests=new ConcurrentHashMap<>();@PostMapping public Map<String,String> create(@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object> ignored){String ref=requests.computeIfAbsent(key,k->"import-"+UUID.randomUUID());return Map.of("reference",ref);}@GetMapping("/count") public Map<String,Integer> count(){return Map.of("count",requests.size());}}
